    20	    public void getOccupancyReport(Context ctx) {
    21	        try {
    22	            String dateStr = ctx.queryParam("date");
    23	            if (dateStr == null || dateStr.isEmpty()) {
    24	                throw new BadRequestResponse("Missing required parameter: date");
    25	            }
    26	
    27	            LocalDate date = parseDate(dateStr);
    28	            String csv = reportService.generateOccupancyReport(date);
    29	            ctx.contentType("text/csv; charset=utf-8").result(csv);
    30	        } catch (Exception e) {
    31	            handleException(ctx, e);
    32	        }
    33	    }
    34	
    35	    public void getRevenueReport(Context ctx) {
    36	        try {
    37	            String monthStr = ctx.queryParam("month");
    38	            if (monthStr == null || monthStr.isEmpty()) {
    39	                throw new BadRequestResponse("Missing required parameter: month");
    40	            }
    41	
    42	            try {
    43	                YearMonth ym = YearMonth.parse(monthStr);
    44	                String csv = reportService.generateRevenueReport(ym.getYear(), ym.getMonthValue());
    45	                ctx.contentType("text/csv; charset=utf-8").result(csv);
