   159	
   160	    private JsonObject reservationToJson(Reservation reservation) {
   161	        JsonObject obj = new JsonObject();
   162	        obj.addProperty("id", reservation.getId());
   163	        obj.addProperty("roomNumber", reservation.getRoomNumber());
   164	        obj.addProperty("guestName", reservation.getGuestName());
   165	        obj.addProperty("guestEmail", reservation.getGuestEmail());
   166	        obj.addProperty("guestCpf", reservation.getGuestCpf());
   167	        obj.addProperty("checkIn", reservation.getCheckIn().toString());
   168	        obj.addProperty("checkOut", reservation.getCheckOut().toString());
   169	        obj.addProperty("guests", reservation.getGuests());
   170	        obj.addProperty("ratePlan", reservation.getRatePlan().getValue());
   171	        obj.addProperty("nights", reservation.getNights());
   172	        obj.addProperty("subtotal", reservation.getSubtotal().doubleValue());
   173	        obj.addProperty("discount", reservation.getDiscount().doubleValue());
   174	        obj.addProperty("total", reservation.getTotal().doubleValue());
   175	        obj.addProperty("status", reservation.getStatus().name());
   176	        obj.addProperty("amountPaid", reservation.getAmountPaid().doubleValue());
   177	
   178	        if (reservation.getRefund() != null) {
   179	            obj.addProperty("refund", reservation.getRefund().doubleValue());
   180	        } else {
   181	            obj.add("refund", null);
   182	        }
   183	
   184	        return obj;
   185	    }
   186	
   187	    private String getRoomType(int roomNumber) throws Exception {
   188	        return switch (roomNumber) {
   189	            case 101, 102 -> "STANDARD";
   190	            case 201, 202 -> "DELUXE";
   191	            case 301 -> "SUITE";
   192	            default -> "UNKNOWN";
   193	        };
   194	    }
   195	}
