    21	
    22	    public String generateOccupancyReport(LocalDate date) throws Exception {
    23	        List<Reservation> reservations = reservationRepository.getConfirmedReservationsByDate(date);
    24	        List<Room> rooms = roomRepository.getAllRooms();
    25	
    26	        StringBuilder csv = new StringBuilder();
    27	        csv.append("room,type,reservation,check_in,check_out\n");
    28	
    29	        int occupiedRooms = 0;
    30	        for (Room room : rooms) {
    31	            boolean occupied = false;
    32	            for (Reservation res : reservations) {
    33	                if (res.getRoomNumber() == room.getNumber()) {
    34	                    csv.append(room.getNumber()).append(",")
    35	                       .append(room.getType().getName()).append(",")
    36	                       .append(res.getId()).append(",")
    37	                       .append(formatDate(res.getCheckIn())).append(",")
    38	                       .append(formatDate(res.getCheckOut())).append("\n");
    39	                    occupied = true;
    40	                    break;
    41	                }
    42	            }
    43	            if (occupied) {
    44	                occupiedRooms++;
    45	            }
    46	        }
    47	
    48	        csv.append("total,").append(occupiedRooms).append("/").append(rooms.size());
    49	        return csv.toString();
    50	    }
    51	
    52	    public String generateRevenueReport(int year, int month) throws Exception {
    53	        List<Reservation> reservations = reservationRepository.getReservationsByMonthAndStatus(year, month);
    54	        List<Room> rooms = roomRepository.getAllRooms();
    55	
    56	        StringBuilder csv = new StringBuilder();
    57	        csv.append("reservation,room,check_in,check_out,status,amount\n");
    58	
    59	        BigDecimal total = BigDecimal.ZERO;
    60	        for (Reservation res : reservations) {
    61	            BigDecimal amount = calculateRevenue(res);
    62	            total = total.add(amount);
    63	
    64	            csv.append(res.getId()).append(",")
    65	               .append(res.getRoomNumber()).append(",")
    66	               .append(formatDateDash(res.getCheckIn())).append(",")
    67	               .append(formatDateDash(res.getCheckOut())).append(",")
    68	               .append(res.getStatus().name()).append(",")
    69	               .append(formatMoneyDash(amount)).append("\n");
    70	        }
    71	
    72	        csv.append("total,,,,").append(formatMoneyDash(total));
    73	        return csv.toString();
    74	    }
