    76	    private BigDecimal calculateRevenue(Reservation reservation) {
    77	        if (reservation.getAmountPaid() == null) {
    78	            return BigDecimal.ZERO;
    79	        }
    80	
    81	        BigDecimal paid = reservation.getAmountPaid();
    82	        BigDecimal refund = reservation.getRefund() != null ? reservation.getRefund() : BigDecimal.ZERO;
    83	        return paid.subtract(refund);
