    32	    public Reservation createReservation(
    33	            int roomNumber,
    34	            String guestName,
    35	            String guestEmail,
    36	            String guestCpf,
    37	            LocalDate checkIn,
    38	            LocalDate checkOut,
    39	            int guests,
    40	            RatePlan ratePlan
    41	    ) throws Exception {
    42	        Room room = roomRepository.getRoomByNumber(roomNumber);
    43	        if (room == null) {
    44	            throw new IllegalArgumentException("ROOM_NOT_FOUND");
    45	        }
    46	
    47	        if (guests < 1 || guests > room.getCapacity()) {
    48	            throw new IllegalArgumentException("CAPACITY_EXCEEDED");
    49	        }
    50	
    51	        if (checkOut.isBefore(checkIn) || checkOut.isEqual(checkIn)) {
    52	            throw new IllegalArgumentException("INVALID_REQUEST");
    53	        }
    54	
    55	        List<Reservation> conflicts = reservationRepository.getReservationsByRoomAndDate(roomNumber, checkIn);
    56	        for (Reservation r : conflicts) {
    57	            if (r.getCheckOut().isAfter(checkIn) && r.getCheckIn().isBefore(checkOut)) {
    58	                throw new IllegalArgumentException("ROOM_UNAVAILABLE");
    59	            }
    60	        }
    61	
    62	        int nights = (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
    63	        BigDecimal subtotal = PriceCalculator.calculateSubtotal(room.getNightlyRate(), checkIn, checkOut);
    64	        BigDecimal discount = PriceCalculator.calculateDiscount(subtotal, ratePlan == RatePlan.NON_REFUNDABLE);
    65	        BigDecimal total = PriceCalculator.calculateTotal(subtotal, discount);
    66	
    67	        long reservationId = reservationRepository.create(
    68	            roomNumber,
    69	            guestName,
    70	            guestEmail,
    71	            guestCpf,
    72	            checkIn,
    73	            checkOut,
    74	            guests,
    75	            ratePlan,
    76	            nights,
    77	            subtotal,
    78	            discount,
    79	            total
    80	        );
    81	
    82	        return reservationRepository.getById(reservationId);
    83	    }
