   173	    public String buildComprovante(Reservation reservation, String roomType) {
   174	        String nights = reservation.getNights() == 1 ? "1 diária" : reservation.getNights() + " diárias";
   175	
   176	        StringBuilder sb = new StringBuilder();
   177	        sb.append("Comprovante de reserva nº ").append(reservation.getId()).append("\n");
   178	        sb.append("Hóspede: ").append(reservation.getGuestName())
   179	          .append(" (CPF ").append(formatCpf(reservation.getGuestCpf())).append(")\n");
   180	        sb.append("Quarto: ").append(reservation.getRoomNumber())
   181	          .append(" (").append(roomType).append(")\n");
   182	        sb.append("Entrada: ").append(formatDate(reservation.getCheckIn()))
   183	          .append(" | Saída: ").append(formatDate(reservation.getCheckOut()))
   184	          .append(" | ").append(nights).append("\n");
   185	        sb.append("Diárias: ").append(formatMoney(reservation.getSubtotal())).append("\n");
   186	
   187	        if (reservation.getDiscount().signum() > 0) {
   188	            sb.append("Desconto: ").append(formatMoney(reservation.getDiscount())).append("\n");
   189	        }
   190	
   191	        sb.append("Total: ").append(formatMoney(reservation.getTotal()));
   192	
   193	        return sb.toString();
   194	    }
   195	
   196	    private String formatDate(LocalDate date) {
   197	        return String.format("%02d/%02d/%04d", date.getDayOfMonth(), date.getMonthValue(), date.getYear());
   198	    }
   199	
   200	    private String formatMoney(BigDecimal value) {
   201	        DecimalFormat df = new DecimalFormat("#,##0.00");
   202	        DecimalFormatSymbols dfs = new DecimalFormatSymbols();
   203	        dfs.setGroupingSeparator('.');
   204	        dfs.setDecimalSeparator(',');
   205	        df.setDecimalFormatSymbols(dfs);
   206	        return "R$ " + df.format(value);
   207	    }
