     3	import java.math.BigDecimal;
     4	import java.math.RoundingMode;
     5	import java.time.LocalDate;
     6	import java.time.YearMonth;
     7	
     8	public class PriceCalculator {
     9	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
    10	    private static final BigDecimal DISCOUNT_RATE = new BigDecimal("0.15");
    11	    private static final RoundingMode ROUNDING_MODE = RoundingMode.HALF_EVEN;
    12	
    13	    public static BigDecimal calculateNightlyPrice(BigDecimal baseRate, LocalDate date) {
    14	        if (isHighSeason(date)) {
    15	            return baseRate.multiply(HIGH_SEASON_MULTIPLIER).setScale(2, ROUNDING_MODE);
    16	        }
    17	        return baseRate.setScale(2, ROUNDING_MODE);
    18	    }
    19	
    20	    public static BigDecimal calculateSubtotal(BigDecimal baseRate, LocalDate checkIn, LocalDate checkOut) {
    21	        BigDecimal subtotal = BigDecimal.ZERO;
    22	        LocalDate current = checkIn;
    23	
    24	        while (current.isBefore(checkOut)) {
    25	            subtotal = subtotal.add(calculateNightlyPrice(baseRate, current));
    26	            current = current.plusDays(1);
    27	        }
    28	
    29	        return subtotal.setScale(2, ROUNDING_MODE);
    30	    }
    31	
    32	    public static BigDecimal calculateDiscount(BigDecimal subtotal, boolean isNonRefundable) {
    33	        if (isNonRefundable) {
    34	            return subtotal.multiply(DISCOUNT_RATE).setScale(2, ROUNDING_MODE);
    35	        }
    36	        return BigDecimal.ZERO.setScale(2, ROUNDING_MODE);
    37	    }
    38	
    39	    public static BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
    40	        return subtotal.subtract(discount).setScale(2, ROUNDING_MODE);
    41	    }
    42	
    43	    private static boolean isHighSeason(LocalDate date) {
    44	        int month = date.getMonthValue();
    45	
    46	        if (month == 7) {
    47	            return true;
    48	        }
    49	
    50	        if (month == 12 || month == 1 || month == 2) {
    51	            return true;
    52	        }
    53	
    54	        return false;
    55	    }
    56	}
