    14	import java.time.LocalDate;
    15	import java.util.List;
    16	
    17	public class ReservationService {
    18	    private final ReservationRepository reservationRepository;
    19	    private final RoomRepository roomRepository;
    20	    private final MessageService messageService;
    21	
    22	    public ReservationService(
    23	            ReservationRepository reservationRepository,
    24	            RoomRepository roomRepository,
    25	            MessageRepository messageRepository
    26	    ) {
    27	        this.reservationRepository = reservationRepository;
    28	        this.roomRepository = roomRepository;
    29	        this.messageService = new MessageService(messageRepository);
    30	    }
    31	
    32	    public Reservation createReservation(
    33	            int roomNumber,
    34	            String guestName,
    35	            String guestEmail,
    36	            String guestCpf,
    37	            LocalDate checkIn,
    38	            LocalDate checkOut,
    39	            int guests,
    40	            RatePlan ratePlan
    41	    ) throws Exception {
    42	        Room room = roomRepository.getRoomByNumber(roomNumber);
    43	        if (room == null) {
    44	            throw new IllegalArgumentException("ROOM_NOT_FOUND");
    45	        }
    46	
    47	        if (guests < 1 || guests > room.getCapacity()) {
    48	            throw new IllegalArgumentException("CAPACITY_EXCEEDED");
    49	        }
    50	
    51	        if (checkOut.isBefore(checkIn) || checkOut.isEqual(checkIn)) {
    52	            throw new IllegalArgumentException("INVALID_REQUEST");
    53	        }
    54	
    55	        List<Reservation> conflicts = reservationRepository.getReservationsByRoomAndDate(roomNumber, checkIn);
    56	        for (Reservation r : conflicts) {
    57	            if (r.getCheckOut().isAfter(checkIn) && r.getCheckIn().isBefore(checkOut)) {
    58	                throw new IllegalArgumentException("ROOM_UNAVAILABLE");
    59	            }
    60	        }
    61	
    62	        int nights = (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
    63	        BigDecimal subtotal = PriceCalculator.calculateSubtotal(room.getNightlyRate(), checkIn, checkOut);
    64	        BigDecimal discount = PriceCalculator.calculateDiscount(subtotal, ratePlan == RatePlan.NON_REFUNDABLE);
    65	        BigDecimal total = PriceCalculator.calculateTotal(subtotal, discount);
    66	
    67	        long reservationId = reservationRepository.create(
    68	            roomNumber,
    69	            guestName,
    70	            guestEmail,
    71	            guestCpf,
    72	            checkIn,
    73	            checkOut,
    74	            guests,
    75	            ratePlan,
    76	            nights,
    77	            subtotal,
    78	            discount,
    79	            total
    80	        );
    81	
    82	        return reservationRepository.getById(reservationId);
    83	    }
    84	
    85	    public Reservation getReservation(long id) throws Exception {
    86	        Reservation reservation = reservationRepository.getById(id);
    87	        if (reservation == null) {
    88	            throw new IllegalArgumentException("RESERVATION_NOT_FOUND");
    89	        }
    90	        return reservation;
    91	    }
    92	
    93	    public Reservation confirmReservation(long id, BigDecimal amountPaid) throws Exception {
    94	        Reservation reservation = getReservation(id);
    95	
    96	        if (reservation.getStatus() != ReservationStatus.PENDING) {
    97	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
    98	        }
    99	
   100	        reservationRepository.updateAmountPaid(id, amountPaid);
   101	        Reservation updated = getReservation(id);
   102	
   103	        Room room = roomRepository.getRoomByNumber(reservation.getRoomNumber());
   104	        sendConfirmationEmail(updated, room.getType().getName());
   105	
   106	        return updated;
   107	    }
   108	
   109	    public Reservation checkIn(long id) throws Exception {
   110	        Reservation reservation = getReservation(id);
   111	
   112	        if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
   113	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
   114	        }
   115	
   116	        reservationRepository.updateStatus(id, ReservationStatus.CHECKED_IN);
   117	        return getReservation(id);
   118	    }
   119	
   120	    public Reservation checkOut(long id) throws Exception {
   121	        Reservation reservation = getReservation(id);
   122	
   123	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
   124	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
   125	        }
   126	
   127	        reservationRepository.updateStatus(id, ReservationStatus.CHECKED_OUT);
   128	        return getReservation(id);
   129	    }
   130	
   131	    public Reservation cancelReservation(long id) throws Exception {
   132	        Reservation reservation = getReservation(id);
   133	
   134	        if (reservation.getStatus() == ReservationStatus.CHECKED_OUT ||
   135	            reservation.getStatus() == ReservationStatus.CANCELLED) {
   136	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
   137	        }
   138	
   139	        BigDecimal refund = calculateRefund(reservation);
   140	        reservationRepository.updateRefund(id, refund);
   141	        return getReservation(id);
   142	    }
   143	
   144	    private BigDecimal calculateRefund(Reservation reservation) {
   145	        if (reservation.getStatus() == ReservationStatus.PENDING) {
   146	            return BigDecimal.ZERO;
   147	        }
   148	
   149	        if (reservation.isRefundable()) {
   150	            return reservation.getAmountPaid();
   151	        }
   152	
   153	        return BigDecimal.ZERO;
   154	    }
   155	
   156	    private void sendConfirmationEmail(Reservation reservation, String roomType) throws Exception {
   157	        String comprovante = buildComprovante(reservation, roomType);
   158	
   159	        String subject = "Reserva confirmada - Pousada Maré Alta";
   160	        String body = String.format(
   161	            "Olá, %s!\n\n" +
   162	            "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n" +
   163	            "%s\n\n" +
   164	            "A entrada é a partir das 14h, e a saída, até as 12h.\n" +
   165	            "Até breve!",
   166	            reservation.getGuestName(),
   167	            comprovante
   168	        );
   169	
   170	        messageService.sendEmail(reservation.getGuestEmail(), subject, body);
   171	    }
   172	
   173	    public String buildComprovante(Reservation reservation, String roomType) {
   174	        String nights = reservation.getNights() == 1 ? "1 diária" : reservation.getNights() + " diárias";
   175	
   176	        StringBuilder sb = new StringBuilder();
   177	        sb.append("Comprovante de reserva nº ").append(reservation.getId()).append("\n");
   178	        sb.append("Hóspede: ").append(reservation.getGuestName())
   179	          .append(" (CPF ").append(formatCpf(reservation.getGuestCpf())).append(")\n");
   180	        sb.append("Quarto: ").append(reservation.getRoomNumber())
   181	          .append(" (").append(roomType).append(")\n");
   182	        sb.append("Entrada: ").append(formatDate(reservation.getCheckIn()))
   183	          .append(" | Saída: ").append(formatDate(reservation.getCheckOut()))
   184	          .append(" | ").append(nights).append("\n");
   185	        sb.append("Diárias: ").append(formatMoney(reservation.getSubtotal())).append("\n");
   186	
   187	        if (reservation.getDiscount().signum() > 0) {
   188	            sb.append("Desconto: ").append(formatMoney(reservation.getDiscount())).append("\n");
   189	        }
   190	
   191	        sb.append("Total: ").append(formatMoney(reservation.getTotal()));
   192	
   193	        return sb.toString();
   194	    }
   195	
   196	    private String formatDate(LocalDate date) {
   197	        return String.format("%02d/%02d/%04d", date.getDayOfMonth(), date.getMonthValue(), date.getYear());
   198	    }
   199	
   200	    private String formatMoney(BigDecimal value) {
   201	        DecimalFormat df = new DecimalFormat("#,##0.00");
   202	        DecimalFormatSymbols dfs = new DecimalFormatSymbols();
   203	        dfs.setGroupingSeparator('.');
   204	        dfs.setDecimalSeparator(',');
   205	        df.setDecimalFormatSymbols(dfs);
   206	        return "R$ " + df.format(value);
   207	    }
   208	
   209	    private String formatCpf(String cpf) {
   210	        return cpf.replaceAll("(\\d{3})(\\d{3})(\\d{3})(\\d{2})", "$1.$2.$3-$4");
   211	    }
   212	}
