     1	package com.pousada.marealta.messaging.processors;
     2	
     3	import com.pousada.marealta.messaging.MessageData;
     4	import com.pousada.marealta.messaging.MessageProcessor;
     5	import com.pousada.marealta.domain.MessageStatus;
     6	
     7	public class EmailValidationProcessor implements MessageProcessor {
     8	    private final boolean enabled;
     9	
    10	    public EmailValidationProcessor(boolean enabled) {
    11	        this.enabled = enabled;
    12	    }
    13	
    14	    @Override
    15	    public void process(MessageData message) {
    16	        if (!enabled || message.isBlocked()) {
    17	            return;
    18	        }
    19	
    20	        if (!isValidEmail(message.getTo())) {
    21	            message.setStatus(MessageStatus.BLOCKED);
    22	            message.setShouldGenerateCopy(false);
    23	        }
    24	    }
    25	
    26	    private boolean isValidEmail(String email) {
    27	        if (email == null || email.isEmpty()) {
    28	            return false;
    29	        }
    30	
    31	        int atIndex = email.indexOf('@');
    32	        if (atIndex < 1) {
    33	            return false;
    34	        }
    35	
    36	        int lastAtIndex = email.lastIndexOf('@');
    37	        if (atIndex != lastAtIndex) {
    38	            return false;
    39	        }
    40	
    41	        String afterAt = email.substring(atIndex + 1);
    42	        if (afterAt.isEmpty()) {
    43	            return false;
    44	        }
    45	
    46	        int dotIndex = afterAt.indexOf('.');
    47	        return dotIndex > 0 && dotIndex < afterAt.length() - 1;
    48	    }
    49	}
